using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.UI;
using UnityEngine.EventSystems;
using System.Collections.Generic;

public class SnowRunnerGame : MonoBehaviour
{
    [Header("Gameplay")]
    public float forwardSpeed = 14f, laneWidth = 2.5f, laneChangeSpeed = 12f, jumpForce = 8.5f, gravity = 23f;
    CharacterController controller; Transform playerRoot, visualRoot; Camera gameCamera;
    int lane=1, coins, bestScore; float verticalSpeed, distance, nextSpawnZ=42f, slideTimer;
    bool gameOver, paused, started, muted; string cameraMode="DYNAMIC";
    readonly List<GameObject> spawned=new List<GameObject>();
    Canvas canvas; Font font; Text distanceText, coinText, titleBestText, titleCoinText, gameOverStats;
    GameObject titlePanel, hudPanel, pausePanel, overPanel, gearPanel;
    readonly Color navy=new Color(.025f,.065f,.13f,.94f), navy2=new Color(.045f,.12f,.21f,.96f), cyan=new Color(.18f,.78f,.96f), gold=new Color(1f,.72f,.12f), red=new Color(.88f,.13f,.17f), white=new Color(.94f,.98f,1f);
    const float playerHeight=1.85f;

    void Start(){Application.targetFrameRate=60; bestScore=PlayerPrefs.GetInt("SnowBest",0); SetupEnvironment();BuildWorld();BuildPlayer();BuildCamera();BuildUI();for(int i=0;i<10;i++)SpawnPattern();ShowTitle();}
    void Update(){if(!started||paused||gameOver)return;
        if(Input.GetKeyDown(KeyCode.Escape)){Pause();return;}
        if(Input.GetKeyDown(KeyCode.A)||Input.GetKeyDown(KeyCode.LeftArrow))lane=Mathf.Max(0,lane-1);
        if(Input.GetKeyDown(KeyCode.D)||Input.GetKeyDown(KeyCode.RightArrow))lane=Mathf.Min(2,lane+1);
        if(controller.isGrounded&&verticalSpeed<0)verticalSpeed=-2f;
        if(controller.isGrounded&&Input.GetKeyDown(KeyCode.Space))verticalSpeed=jumpForce;
        if((Input.GetKeyDown(KeyCode.S)||Input.GetKeyDown(KeyCode.DownArrow))&&slideTimer<=0){slideTimer=.75f;controller.height=1.05f;controller.center=new Vector3(0,.53f,0);visualRoot.localScale=new Vector3(1,.62f,1);}
        if(slideTimer>0){slideTimer-=Time.deltaTime;if(slideTimer<=0){controller.height=playerHeight;controller.center=new Vector3(0,.92f,0);visualRoot.localScale=Vector3.one;}}
        verticalSpeed-=gravity*Time.deltaTime;float targetX=(lane-1)*laneWidth;float xVelocity=(targetX-playerRoot.position.x)*laneChangeSpeed;
        controller.Move(new Vector3(xVelocity,verticalSpeed,forwardSpeed)*Time.deltaTime);distance+=forwardSpeed*Time.deltaTime;
        float run=Mathf.Sin(Time.time*13f);visualRoot.localPosition=new Vector3(0,.04f+Mathf.Abs(run)*.055f,0);visualRoot.localRotation=Quaternion.Euler(0,0,Mathf.Sin(Time.time*6f)*2f);
        if(playerRoot.position.z+100f>=nextSpawnZ)SpawnPattern();
        for(int i=spawned.Count-1;i>=0;i--){GameObject o=spawned[i];if(!o){spawned.RemoveAt(i);continue;}if(o.transform.position.z<playerRoot.position.z-18f){Destroy(o);spawned.RemoveAt(i);}}
        Vector3 camTarget=playerRoot.position+(cameraMode=="HIGH"?new Vector3(0,7.2f,-10.5f):cameraMode=="CLOSE"?new Vector3(0,4.2f,-6.8f):new Vector3(0,5.1f,-8.8f));gameCamera.transform.position=Vector3.Lerp(gameCamera.transform.position,camTarget,7f*Time.deltaTime);gameCamera.transform.LookAt(playerRoot.position+new Vector3(0,1.2f,8f));
        if(distanceText)distanceText.text=Mathf.FloorToInt(distance)+" <size=18>m</size>";
        if(coinText)coinText.text=coins.ToString("00");
    }
    void SetupEnvironment(){RenderSettings.ambientLight=new Color(.55f,.66f,.82f);RenderSettings.fog=true;RenderSettings.fogColor=new Color(.58f,.72f,.86f);RenderSettings.fogMode=FogMode.Linear;RenderSettings.fogStartDistance=90;RenderSettings.fogEndDistance=260;GameObject sun=new GameObject("Arctic Sun");Light l=sun.AddComponent<Light>();l.type=LightType.Directional;l.intensity=1.35f;l.color=new Color(.78f,.88f,1);sun.transform.rotation=Quaternion.Euler(42,-28,0);}
    void BuildWorld(){Cube("Frozen Runway",new Vector3(0,-.42f,520),new Vector3(9,.8f,1120),new Color(.88f,.95f,1),true);Cube("Left Snowbank",new Vector3(-5,.05f,520),new Vector3(1.2f,1.1f,1120),new Color(.72f,.86f,.96f),false);Cube("Right Snowbank",new Vector3(5,.05f,520),new Vector3(1.2f,1.1f,1120),new Color(.72f,.86f,.96f),false);
        for(int z=0;z<1100;z+=16){Cube("Center Ice Dash",new Vector3(0,.012f,z),new Vector3(.055f,.025f,5.5f),new Color(.48f,.76f,.88f),false);for(int side=-1;side<=1;side+=2){Cylinder("Blue Track Marker",new Vector3(side*4.35f,.12f,z),new Vector3(.11f,.22f,.11f),new Color(.28f,.72f,.86f));if(z%32==0)MakeTree(side*Random.Range(8f,13f),z+Random.Range(-4f,4f));}}
        for(int i=0;i<22;i++){float x=(i%2==0?-1:1)*Random.Range(20f,42f);float z=Random.Range(15f,1000f);Sphere("Distant Ice Peak",new Vector3(x,Random.Range(5f,12f),z),new Vector3(Random.Range(9f,17f),Random.Range(12f,24f),Random.Range(12f,25f)),new Color(.58f,.72f,.84f),false);}}
    void MakeTree(float x,float z){Cylinder("Pine Trunk",new Vector3(x,1.1f,z),new Vector3(.35f,1.2f,.35f),new Color(.22f,.16f,.13f));for(int i=0;i<3;i++)Sphere("Snow Pine",new Vector3(x,2.4f+i*.85f,z),new Vector3(2.7f-i*.45f,2.7f-i*.35f,2.7f-i*.45f),i==2?new Color(.83f,.93f,.98f):new Color(.055f,.24f,.27f),false);}
    void BuildPlayer(){playerRoot=new GameObject("Player Controller").transform;controller=playerRoot.gameObject.AddComponent<CharacterController>();controller.height=playerHeight;controller.radius=.38f;controller.center=new Vector3(0,.92f,0);visualRoot=new GameObject("Arctic Runner").transform;visualRoot.SetParent(playerRoot,false);visualRoot.localPosition=new Vector3(0,.04f,0);
        Part("Snowboard",PrimitiveType.Cube,new Vector3(0,-.82f,.08f),new Vector3(.92f,.12f,1.35f),new Color(.02f,.35f,.55f));Part("Left Boot",PrimitiveType.Cube,new Vector3(-.2f,-.62f,.12f),new Vector3(.25f,.32f,.38f),Color.black);Part("Right Boot",PrimitiveType.Cube,new Vector3(.2f,-.62f,.12f),new Vector3(.25f,.32f,.38f),Color.black);
        Part("Left Trouser",PrimitiveType.Capsule,new Vector3(-.2f,-.32f,0),new Vector3(.22f,.55f,.23f),new Color(.035f,.13f,.25f));Part("Right Trouser",PrimitiveType.Capsule,new Vector3(.2f,-.32f,0),new Vector3(.22f,.55f,.23f),new Color(.035f,.13f,.25f));Part("Red Expedition Jacket",PrimitiveType.Capsule,new Vector3(0,.25f,0),new Vector3(.62f,.72f,.4f),new Color(.82f,.12f,.12f));Part("Jacket Stripe",PrimitiveType.Cube,new Vector3(0,.25f,.205f),new Vector3(.08f,.55f,.025f),gold);Part("Backpack",PrimitiveType.Cube,new Vector3(0,.32f,-.27f),new Vector3(.42f,.5f,.2f),new Color(.04f,.23f,.34f));Part("Left Sleeve",PrimitiveType.Capsule,new Vector3(-.43f,.28f,.02f),new Vector3(.2f,.56f,.2f),red,new Vector3(0,0,-24));Part("Right Sleeve",PrimitiveType.Capsule,new Vector3(.43f,.28f,.02f),new Vector3(.2f,.56f,.2f),red,new Vector3(0,0,24));Part("Face",PrimitiveType.Sphere,new Vector3(0,.88f,.015f),new Vector3(.37f,.4f,.34f),new Color(.88f,.66f,.52f));Part("Helmet",PrimitiveType.Sphere,new Vector3(0,1.04f,-.005f),new Vector3(.43f,.29f,.39f),new Color(.03f,.25f,.42f));Part("Goggles",PrimitiveType.Cube,new Vector3(0,.91f,.29f),new Vector3(.34f,.11f,.035f),new Color(.12f,.8f,.95f));Part("Scarf",PrimitiveType.Cube,new Vector3(0,.62f,.12f),new Vector3(.42f,.13f,.32f),gold);}
    void BuildCamera(){GameObject c=new GameObject("Main Camera");c.tag="MainCamera";gameCamera=c.AddComponent<Camera>();gameCamera.fieldOfView=62;c.AddComponent<AudioListener>();c.transform.position=new Vector3(0,5.1f,-8.8f);c.transform.LookAt(new Vector3(0,1.2f,8));}
    void BuildUI(){font=Resources.GetBuiltinResource<Font>("Arial.ttf");GameObject ev=new GameObject("EventSystem");ev.AddComponent<EventSystem>();ev.AddComponent<StandaloneInputModule>();GameObject root=new GameObject("Snow Runner UI",typeof(Canvas),typeof(CanvasScaler),typeof(GraphicRaycaster));canvas=root.GetComponent<Canvas>();canvas.renderMode=RenderMode.ScreenSpaceOverlay;canvas.sortingOrder=20;CanvasScaler scaler=root.GetComponent<CanvasScaler>();scaler.uiScaleMode=CanvasScaler.ScaleMode.ScaleWithScreenSize;scaler.referenceResolution=new Vector2(1920,1080);scaler.matchWidthOrHeight=.5f;
        titlePanel=Panel("Title Screen",new Vector2(0,0),new Vector2(1,1),new Color(.02f,.07f,.14f,.20f));hudPanel=Panel("Gameplay HUD",new Vector2(0,0),new Vector2(1,1),new Color(0,0,0,0));pausePanel=Panel("Pause Overlay",new Vector2(0,0),new Vector2(1,1),new Color(0,0,0,.68f));overPanel=Panel("Game Over Overlay",new Vector2(0,0),new Vector2(1,1),new Color(0,0,0,.7f));gearPanel=Panel("Basecamp Gear",new Vector2(0,0),new Vector2(1,1),new Color(0,0,0,.72f));
        BuildTitleUI();BuildHudUI();BuildPauseUI();BuildOverUI();BuildGearUI();}
    GameObject Panel(string n,Vector2 amin,Vector2 amax,Color c){GameObject o=new GameObject(n,typeof(RectTransform),typeof(Image));o.transform.SetParent(canvas.transform,false);RectTransform r=o.GetComponent<RectTransform>();r.anchorMin=amin;r.anchorMax=amax;r.offsetMin=Vector2.zero;r.offsetMax=Vector2.zero;o.GetComponent<Image>().color=c;return o;}
    Text Label(Transform parent,string value,int size,Color color,Vector2 anchor,Vector2 pos,Vector2 dims,TextAnchor align=TextAnchor.MiddleCenter){GameObject o=new GameObject("Text - "+value,typeof(RectTransform),typeof(Text));o.transform.SetParent(parent,false);RectTransform r=o.GetComponent<RectTransform>();r.anchorMin=anchor;r.anchorMax=anchor;r.pivot=new Vector2(.5f,.5f);r.anchoredPosition=pos;r.sizeDelta=dims;Text t=o.GetComponent<Text>();t.font=font;t.text=value;t.fontSize=size;t.fontStyle=FontStyle.Bold;t.color=color;t.alignment=align;t.horizontalOverflow=HorizontalWrapMode.Wrap;t.verticalOverflow=VerticalWrapMode.Overflow;t.supportRichText=true;return t;}
    Image Box(Transform p,Vector2 anchor,Vector2 pos,Vector2 size,Color color){GameObject o=new GameObject("Panel",typeof(RectTransform),typeof(Image));o.transform.SetParent(p,false);RectTransform r=o.GetComponent<RectTransform>();r.anchorMin=anchor;r.anchorMax=anchor;r.pivot=new Vector2(.5f,.5f);r.anchoredPosition=pos;r.sizeDelta=size;Image im=o.GetComponent<Image>();im.color=color;return im;}
    Button Btn(Transform p,string text,Vector2 anchor,Vector2 pos,Vector2 size,Color color,UnityEngine.Events.UnityAction action,int fontSize=24){GameObject o=new GameObject("Button - "+text,typeof(RectTransform),typeof(Image),typeof(Button));o.transform.SetParent(p,false);RectTransform r=o.GetComponent<RectTransform>();r.anchorMin=anchor;r.anchorMax=anchor;r.pivot=new Vector2(.5f,.5f);r.anchoredPosition=pos;r.sizeDelta=size;Image im=o.GetComponent<Image>();im.color=color;Button b=o.GetComponent<Button>();ColorBlock cb=b.colors;cb.normalColor=color;cb.highlightedColor=Color.Lerp(color,Color.white,.18f);cb.pressedColor=Color.Lerp(color,Color.black,.18f);b.colors=cb;b.onClick.AddListener(action);Label(o.transform,text,fontSize,white,new Vector2(.5f,.5f),Vector2.zero,size);return b;}
    void BuildTitleUI(){Box(titlePanel.transform,new Vector2(.5f,.5f),Vector2.zero,new Vector2(820,610),new Color(.025f,.07f,.13f,.83f));Label(titlePanel.transform,"SNOW PEAK",30,new Color(.72f,.9f,1),new Vector2(.5f,1),new Vector2(0,-120),new Vector2(700,45));Label(titlePanel.transform,"SNOW\nRUSH",100,white,new Vector2(.5f,1),new Vector2(0,-270),new Vector2(700,210));Label(titlePanel.transform,"DODGE THE AVALANCHE  •  OWN THE MOUNTAIN",20,cyan,new Vector2(.5f,1),new Vector2(0,-390),new Vector2(700,40));Btn(titlePanel.transform,"START CLIMB   ▶",new Vector2(.5f,.5f),new Vector2(0,-55),new Vector2(390,78),red,StartGame,30);Btn(titlePanel.transform,"BASECAMP GEAR",new Vector2(.5f,.5f),new Vector2(0,-150),new Vector2(300,58),navy2,ShowGear,22);titleCoinText=Label(titlePanel.transform,"🟡  0 COINS",22,gold,new Vector2(.5f,0),new Vector2(-160,80),new Vector2(260,45));titleBestText=Label(titlePanel.transform,"🏆  BEST  0 m",22,white,new Vector2(.5f,0),new Vector2(160,80),new Vector2(280,45));Label(titlePanel.transform,"A / D  MOVE     SPACE  JUMP     S  SLIDE     ESC  PAUSE",17,new Color(.78f,.88f,.96f),new Vector2(.5f,0),new Vector2(0,25),new Vector2(700,35));Btn(titlePanel.transform,"CAMERA",new Vector2(0,1),new Vector2(105,-65),new Vector2(160,48),navy2,CycleCamera,18);Btn(titlePanel.transform,"SOUND  ON",new Vector2(1,1),new Vector2(-110,-65),new Vector2(170,48),navy2,ToggleSound,18);}
    void BuildHudUI(){Box(hudPanel.transform,new Vector2(0,1),new Vector2(145,-85),new Vector2(245,92),navy);Label(hudPanel.transform,"ALTITUDE",15,cyan,new Vector2(0,1),new Vector2(145,-58),new Vector2(220,25));distanceText=Label(hudPanel.transform,"0 m",34,white,new Vector2(0,1),new Vector2(145,-105),new Vector2(220,50));Box(hudPanel.transform,new Vector2(0,1),new Vector2(145,-190),new Vector2(245,58),navy);Label(hudPanel.transform,"🟡  COINS",15,gold,new Vector2(0,1),new Vector2(95,-190),new Vector2(110,42));coinText=Label(hudPanel.transform,"00",23,white,new Vector2(0,1),new Vector2(205,-190),new Vector2(70,42));Btn(hudPanel.transform,"Ⅱ  PAUSE",new Vector2(1,1),new Vector2(-105,-65),new Vector2(170,55),navy2,Pause,20);Label(hudPanel.transform,"A / D  MOVE     SPACE  JUMP     S  SLIDE",15,white,new Vector2(.5f,0),new Vector2(0,38),new Vector2(700,42));Btn(hudPanel.transform,"◀",new Vector2(0,0),new Vector2(80,125),new Vector2(95,75),navy2,()=>lane=Mathf.Max(0,lane-1),30);Btn(hudPanel.transform,"▶",new Vector2(0,0),new Vector2(190,125),new Vector2(95,75),navy2,()=>lane=Mathf.Min(2,lane+1),30);Btn(hudPanel.transform,"JUMP",new Vector2(1,0),new Vector2(-185,125),new Vector2(125,75),new Color(.12f,.42f,.66f),()=>{if(controller.isGrounded)verticalSpeed=jumpForce;},18);Btn(hudPanel.transform,"SLIDE",new Vector2(1,0),new Vector2(-65,125),new Vector2(105,75),new Color(.12f,.3f,.4f),()=>{if(slideTimer<=0){slideTimer=.75f;controller.height=1.05f;controller.center=new Vector3(0,.53f,0);visualRoot.localScale=new Vector3(1,.62f,1);}},16);}
    void BuildPauseUI(){Box(pausePanel.transform,new Vector2(.5f,.5f),Vector2.zero,new Vector2(560,600),navy);Label(pausePanel.transform,"EXPEDITION PAUSED",38,white,new Vector2(.5f,.5f),new Vector2(0,205),new Vector2(500,60));Label(pausePanel.transform,"Take a breath. The summit can wait.",18,cyan,new Vector2(.5f,.5f),new Vector2(0,155),new Vector2(500,40));Btn(pausePanel.transform,"RESUME CLIMB",new Vector2(.5f,.5f),new Vector2(0,55),new Vector2(380,65),red,Resume,24);Btn(pausePanel.transform,"RESTART RUN",new Vector2(.5f,.5f),new Vector2(0,-30),new Vector2(380,58),navy2,Restart,21);Btn(pausePanel.transform,"EXIT TO BASECAMP",new Vector2(.5f,.5f),new Vector2(0,-110),new Vector2(380,58),navy2,ShowTitle,21);Btn(pausePanel.transform,"CAMERA: CYCLE",new Vector2(.5f,.5f),new Vector2(0,-195),new Vector2(260,48),new Color(.08f,.2f,.3f),CycleCamera,17);}
    void BuildOverUI(){Box(overPanel.transform,new Vector2(.5f,.5f),Vector2.zero,new Vector2(590,500),navy);Label(overPanel.transform,"RUN ENDED",48,red,new Vector2(.5f,.5f),new Vector2(0,165),new Vector2(500,70));gameOverStats=Label(overPanel.transform,"DISTANCE  0 m\nCOINS  0",25,white,new Vector2(.5f,.5f),new Vector2(0,70),new Vector2(450,100));Btn(overPanel.transform,"RUN AGAIN",new Vector2(.5f,.5f),new Vector2(0,-50),new Vector2(360,65),red,Restart,24);Btn(overPanel.transform,"BACK TO BASECAMP",new Vector2(.5f,.5f),new Vector2(0,-135),new Vector2(360,58),navy2,ShowTitle,20);}
    void BuildGearUI(){Box(gearPanel.transform,new Vector2(.5f,.5f),Vector2.zero,new Vector2(600,500),navy);Label(gearPanel.transform,"BASECAMP GEAR",38,white,new Vector2(.5f,.5f),new Vector2(0,160),new Vector2(500,60));Label(gearPanel.transform,"Your expedition kit is ready.\nUpgrades will be available in a later build.",21,cyan,new Vector2(.5f,.5f),new Vector2(0,35),new Vector2(480,100));Btn(gearPanel.transform,"BACK",new Vector2(.5f,.5f),new Vector2(0,-130),new Vector2(300,60),red,HideGear,22);}
    void SetOnly(GameObject active){titlePanel.SetActive(active==titlePanel);hudPanel.SetActive(active==hudPanel);pausePanel.SetActive(active==pausePanel);overPanel.SetActive(active==overPanel);gearPanel.SetActive(active==gearPanel);}
    void ShowTitle(){started=false;paused=false;gameOver=false;Time.timeScale=1;SetOnly(titlePanel);titleCoinText.text="🟡  "+coins+" COINS";titleBestText.text="🏆  BEST  "+bestScore+" m";}
    void StartGame(){if(gameOver||started){SceneManager.LoadScene(SceneManager.GetActiveScene().buildIndex);return;}started=true;paused=false;gameOver=false;distance=0;coins=0;lane=1;playerRoot.position=Vector3.zero;verticalSpeed=0;SetOnly(hudPanel);}
    void Pause(){if(!started||gameOver)return;paused=true;SetOnly(pausePanel);}
    void Resume(){paused=false;SetOnly(hudPanel);}
    void Restart(){Time.timeScale=1;SceneManager.LoadScene(SceneManager.GetActiveScene().buildIndex);}
    void ShowGear(){SetOnly(gearPanel);} void HideGear(){SetOnly(titlePanel);}
    void CycleCamera(){cameraMode=cameraMode=="DYNAMIC"?"CLOSE":cameraMode=="CLOSE"?"HIGH":"DYNAMIC";}
    void ToggleSound(){muted=!muted;AudioListener.pause=muted;}
    void SpawnPattern(){float z=nextSpawnZ;nextSpawnZ+=Random.Range(17f,23f);int blocked=Random.Range(0,3);GameObject obstacle=Cube("Obstacle - Ice Boulder",new Vector3((blocked-1)*laneWidth,.8f,z),new Vector3(1.35f,1.55f,1.2f),new Color(.24f,.55f,.68f),true);obstacle.AddComponent<SnowRunnerObstacle>().game=this;spawned.Add(obstacle);int coinLane=(blocked+Random.Range(1,3))%3;for(int i=0;i<5;i++){GameObject coin=Cylinder("Gold Token",new Vector3((coinLane-1)*laneWidth,1.35f,z+3+i*1.35f),new Vector3(.58f,.12f,.58f),gold);coin.transform.rotation=Quaternion.Euler(90,0,0);coin.GetComponent<Collider>().isTrigger=true;coin.AddComponent<SnowRunnerCoin>().game=this;spawned.Add(coin);}}
    public void Collect(GameObject coin){if(!coin)return;coins++;spawned.Remove(coin);Destroy(coin);if(coinText)coinText.text=coins.ToString("00");}
    public void Crash(){if(gameOver)return;gameOver=true;started=false;int score=Mathf.FloorToInt(distance);if(score>bestScore){bestScore=score;PlayerPrefs.SetInt("SnowBest",bestScore);}gameOverStats.text="DISTANCE  "+score+" m\nCOINS  "+coins+"\nBEST  "+bestScore+" m";SetOnly(overPanel);}
    void OnControllerColliderHit(ControllerColliderHit hit){if(hit.collider.GetComponent<SnowRunnerObstacle>()!=null)Crash();}
    GameObject Part(string n,PrimitiveType type,Vector3 p,Vector3 s,Color color,Vector3? rot=null){GameObject o=GameObject.CreatePrimitive(type);o.name=n;o.transform.SetParent(visualRoot,false);o.transform.localPosition=p;o.transform.localScale=s;if(rot.HasValue)o.transform.localRotation=Quaternion.Euler(rot.Value);o.GetComponent<Renderer>().material.color=color;Destroy(o.GetComponent<Collider>());return o;}
    GameObject Cube(string n,Vector3 p,Vector3 s,Color c,bool col){GameObject o=GameObject.CreatePrimitive(PrimitiveType.Cube);o.name=n;o.transform.position=p;o.transform.localScale=s;o.GetComponent<Renderer>().material.color=c;if(!col)Destroy(o.GetComponent<Collider>());return o;}
    GameObject Sphere(string n,Vector3 p,Vector3 s,Color c,bool col){GameObject o=GameObject.CreatePrimitive(PrimitiveType.Sphere);o.name=n;o.transform.position=p;o.transform.localScale=s;o.GetComponent<Renderer>().material.color=c;if(!col)Destroy(o.GetComponent<Collider>());return o;}
    GameObject Cylinder(string n,Vector3 p,Vector3 s,Color c){GameObject o=GameObject.CreatePrimitive(PrimitiveType.Cylinder);o.name=n;o.transform.position=p;o.transform.localScale=s;o.GetComponent<Renderer>().material.color=c;return o;}
}
public class SnowRunnerCoin:MonoBehaviour{[HideInInspector]public SnowRunnerGame game;void Update(){transform.Rotate(0,180*Time.deltaTime,0,Space.World);}void OnTriggerEnter(Collider other){if(other.GetComponent<CharacterController>()&&game)game.Collect(gameObject);}}
public class SnowRunnerObstacle:MonoBehaviour{[HideInInspector]public SnowRunnerGame game;}
